      "findingType": "missing_next_step",
      "severity": "high",
      "score": 2,
      "suggestion": "Add a clear CTA: 'Download my free Lisbon budget spreadsheet at lisbon.example/spreadsheet linked below.'",
      "sources": [],
      "dimension": "conversion_cta"
    }
  ]
